int create_graphics_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_mode_create_dumb args;
    struct drm_gem_object *obj = NULL;
    struct drm_plane *plane = NULL;

    if (!dev || !file_priv || !data)
        return -EINVAL;

    memcpy(&args, data, sizeof(args));

    if (args.width == 0 || args.height == 0 || args.bpp == 0)
        return -EINVAL;

    obj = drm_gem_object_create(dev, args.height * args.bpp * args.width / 8);
    if (IS_ERR(obj))
        return PTR_ERR(obj);

    plane = kzalloc(sizeof(*plane), GFP_KERNEL);
    if (!plane) {
        ret = -ENOMEM;
        goto free_obj;
    }

    plane->fb = drm_framebuffer_alloc(dev, &args, NULL);
    if (IS_ERR(plane->fb)) {
        ret = PTR_ERR(plane->fb);
        goto free_plane;
    }

    drm_mode_object_add(dev, &plane->base, DRM_MODE_OBJECT_PLANE);

    return 0;

free_plane:
    kfree(plane);
free_obj:
    drm_gem_object_put(obj);
    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_mode_create_dumb args;
    struct drm_gem_object *obj = NULL;
    struct drm_plane *plane = NULL;
    struct drm_framebuffer *fb = NULL;
    struct drm_mode_object *obj_list[2];
    struct drm_plane_state *plane_state;
    struct drm_crtc *crtc = NULL;
    struct drm_crtc_state *crtc_state;
    struct drm_atomic_state *state = NULL;

    if (!dev || !data || !file_priv)
        return ret;

    memcpy(&args, data, sizeof(args));

    obj = drm_gem_object_create(dev, args.size);
    if (IS_ERR(obj))
        return PTR_ERR(obj);

    fb = drm_framebuffer_alloc(dev, 0, obj);
    if (!fb) {
        ret = -ENOMEM;
        goto out_unref_obj;
    }

    plane = list_first_entry(&dev->mode_config.plane_list, struct drm_plane, head);
    if (!plane) {
        ret = -ENODEV;
        goto out_unref_fb;
    }

    plane_state = drm_atomic_get_plane_state(state, plane);
    if (IS_ERR(plane_state)) {
        ret = PTR_ERR(plane_state);
        goto out_unref_fb;
    }

    crtc = list_first_entry(&dev->mode_config.crtc_list, struct drm_crtc, head);
    if (!crtc) {
        ret = -ENODEV;
        goto out_put_plane_state;
    }

    crtc_state = drm_atomic_get_crtc_state(state, crtc);
    if (IS_ERR(crtc_state)) {
        ret = PTR_ERR(crtc_state);
        goto out_put_plane_state;
    }

    ret = drm_mode_object_add(dev, &fb->base, DRM_MODE_OBJECT_FB);
    if (ret)
        goto out_put_crtc_state;

    ret = drm_mode_object_get(dev, &fb->base);
    if (ret)
        goto out_put_crtc_state;

    obj_list[0] = &fb->base;
    obj_list[1] = NULL;

    ret = drm_plane_check_state(plane_state, crtc_state, obj_list, DRM_MODE_ATOMIC_TEST_ONLY);
    if (ret)
        goto out_put_crtc_state;

    ret = drm_mode_object_put(dev, &fb->base);
    if (ret)
        goto out_put_crtc_state;

    return 0;

out_put_crtc_state:
    drm_atomic_put_crtc_state(crtc_state);
out_put_plane_state:
    drm_atomic_put_plane_state(plane_state);
out_unref_fb:
    drm_framebuffer_unregister_private(fb);
    drm_framebuffer_put(fb);
out_unref_obj:
    drm_gem_object_put(obj);
    return ret;
}

