int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_mode_create_arg *arg = data;
    struct drm_gem_object *obj;
    struct drm_plane *plane;
    struct drm_property *zpos_property;
    struct drm_property *rotation_property;

    if (!arg || !dev || !file_priv)
        return -EINVAL;

    obj = drm_gem_object_lookup(file_priv, arg->handle);
    if (!obj)
        return -ENOENT;

    plane = drm_plane_find(dev, arg->plane_id);
    if (!plane) {
        ret = -ENODEV;
        goto out_obj_put;
    }

    zpos_property = drm_mode_find_property(dev, arg->zpos_property_id);
    rotation_property = drm_mode_find_property(dev, arg->rotation_property_id);

    if (!zpos_property || !rotation_property) {
        ret = -EINVAL;
        goto out_plane_put;
    }

    ret = drm_mode_create_user_surface(dev, arg, file_priv);
    if (ret < 0)
        goto out_plane_put;

    return 0;

out_plane_put:
    drm_plane_put(plane);
out_obj_put:
    drm_gem_object_put(obj);
    return ret;
}

int create_guest_graphics_surface(struct drm_device *dev, void *data, struct drm_file *file_priv)
{
    struct drm_virtio_surface_create *args = data;
    struct virtio_guest_surface *surface;
    int ret = 0;

    if (!args) {
        return -EINVAL;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface) {
        return -ENOMEM;
    }

    mutex_lock(&dev->mode_config.mutex);

    /* Perform buffer allocation and surface initialization logic here. */
    ret = drm_gem_object_init(dev, &surface->gem, args->size);
    if (ret) {
        goto unlock_and_free;
    }

    surface->pitch = args->pitch;
    surface->format = args->format;

    /* Add surface to device's resource list or handle as per logic. */

    mutex_unlock(&dev->mode_config.mutex);

    args->handle = surface->gem.handle;
    return 0;

unlock_and_free:
    mutex_unlock(&dev->mode_config.mutex);
    kfree(surface);
    return ret;
}
